-- Archived: 2026-04-21
-- Source:   thyroid_canonical_publication_v1_0.main.canonical_us_exam_master_v2
-- New name: thyroid_canonical_publication_v1_0.main.canonical_us_exam_master_VIEW_v2
-- Reason:   view labeling pass — add _VIEW suffix

CREATE VIEW canonical_us_exam_master_v2 AS WITH cpm AS (SELECT research_id, first_surgery_date_v2 FROM thyroid_canonical_publication_v1_0.main.canonical_patient_master), nodule_agg AS (SELECT research_id, exam_date, any_value(us_exam_id) AS us_exam_id_nodule, count_star() AS n_nodules_on_exam, max(size_cm_max) AS largest_nodule_cm, (bool_or((lower(COALESCE(laterality, '')) = 'right')) AND bool_or((lower(COALESCE(laterality, '')) = 'left'))) AS bilateral_flag, (bool_or((lower(COALESCE(laterality, '')) = 'isthmus')) OR bool_or((lower(COALESCE(location_raw, '')) ~~ '%isthmus%'))) AS isthmus_nodule_flag, max(acr2017_tirads_category) AS worst_tirads_category_this_exam, max(acr2017_tirads_points) AS worst_tirads_points_this_exam, min(acr2017_tirads_category) AS best_tirads_category_this_exam, sum(CASE  WHEN ((upper(acr2017_tirads_category) = 'TR5')) THEN (1) ELSE 0 END) AS count_tr5, sum(CASE  WHEN ((upper(acr2017_tirads_category) = 'TR4')) THEN (1) ELSE 0 END) AS count_tr4, sum(CASE  WHEN ((upper(acr2017_tirads_category) = 'TR3')) THEN (1) ELSE 0 END) AS count_tr3, sum(CASE  WHEN ((upper(acr2017_tirads_category) = 'TR2')) THEN (1) ELSE 0 END) AS count_tr2, sum(CASE  WHEN ((upper(acr2017_tirads_category) = 'TR1')) THEN (1) ELSE 0 END) AS count_tr1, bool_or(nlp_backfill_pending) AS any_nodule_pending_on_exam FROM thyroid_canonical_publication_v1_0.main.canonical_us_nodule_v2 WHERE (CAST(is_aggregate_row AS BOOLEAN) IS DISTINCT FROM CAST('t' AS BOOLEAN)) GROUP BY 1, 2), nodule_2nd AS (SELECT research_id, exam_date, nth_value(size_cm_max, 2) OVER (PARTITION BY research_id, exam_date ORDER BY size_cm_max DESC NULLS LAST ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS second_largest_nodule_cm FROM thyroid_canonical_publication_v1_0.main.canonical_us_nodule_v2 WHERE (CAST(is_aggregate_row AS BOOLEAN) IS DISTINCT FROM CAST('t' AS BOOLEAN)) QUALIFY (row_number() OVER (PARTITION BY research_id, exam_date) = 1)), gland_agg AS (SELECT research_id, exam_date, any_value(us_exam_id) AS us_exam_id_gland, CAST('t' AS BOOLEAN) AS has_gland_findings, bool_or(nlp_backfill_pending) AS any_gland_pending_on_exam FROM thyroid_canonical_publication_v1_0.main.canonical_us_thyroid_gland_v2 GROUP BY 1, 2), ln_agg AS (SELECT research_id, exam_date, any_value(us_exam_id) AS us_exam_id_ln, CAST('t' AS BOOLEAN) AS has_us_ln_findings, count_star() AS n_us_ln_total_on_exam, sum(CASE  WHEN ((CAST(suspicious_flag AS BOOLEAN) IS NOT DISTINCT FROM CAST('t' AS BOOLEAN))) THEN (1) ELSE 0 END) AS n_abnormal_us_ln_on_exam, bool_or(nlp_backfill_pending) AS any_us_ln_pending_on_exam FROM thyroid_canonical_publication_v1_0.main.canonical_us_lymph_node_v2 GROUP BY 1, 2), exams AS (((SELECT research_id, exam_date FROM nodule_agg) UNION (SELECT research_id, exam_date FROM gland_agg)) UNION (SELECT research_id, exam_date FROM ln_agg)), joined AS (SELECT exams.research_id, COALESCE(n.us_exam_id_nodule, g.us_exam_id_gland, l.us_exam_id_ln) AS us_exam_id, exams.exam_date, n.n_nodules_on_exam, n.largest_nodule_cm, n2.second_largest_nodule_cm, n.bilateral_flag, n.isthmus_nodule_flag, n.worst_tirads_category_this_exam, n.worst_tirads_points_this_exam, n.best_tirads_category_this_exam, n.count_tr5, n.count_tr4, n.count_tr3, n.count_tr2, n.count_tr1, COALESCE(g.has_gland_findings, CAST('f' AS BOOLEAN)) AS has_gland_findings, COALESCE(l.has_us_ln_findings, CAST('f' AS BOOLEAN)) AS has_us_ln_findings, l.n_us_ln_total_on_exam, l.n_abnormal_us_ln_on_exam, row_number() OVER (PARTITION BY exams.research_id ORDER BY exams.exam_date NULLS LAST) AS exam_rank_for_patient, CASE  WHEN (((cp.first_surgery_date_v2 IS NOT NULL) AND (exams.exam_date <= cp.first_surgery_date_v2))) THEN (CAST('t' AS BOOLEAN)) ELSE CAST('f' AS BOOLEAN) END AS is_preop_exam, (COALESCE(n.any_nodule_pending_on_exam, CAST('f' AS BOOLEAN)) OR COALESCE(g.any_gland_pending_on_exam, CAST('f' AS BOOLEAN)) OR COALESCE(l.any_us_ln_pending_on_exam, CAST('f' AS BOOLEAN))) AS any_nlp_backfill_pending_on_exam FROM exams LEFT JOIN nodule_agg AS n USING (research_id, exam_date) LEFT JOIN nodule_2nd AS n2 USING (research_id, exam_date) LEFT JOIN gland_agg AS g USING (research_id, exam_date) LEFT JOIN ln_agg AS l USING (research_id, exam_date) LEFT JOIN cpm AS cp ON ((cp.research_id = exams.research_id)))SELECT * FROM joined;
